def parse_key_values(text, sep='='):
    result={}
    for line in text.splitlines():
        if not line.strip():
            continue
        if sep not in line:
            raise ValueError('missing separator')
        key,value=line.split(sep,1)
        result[key.strip()]=value.strip()
    return result
```

